def components(graph):
    visited = set()
    count = 0
    for start in graph:
        if start not in visited:
            count += 1
            stack = [start]
            while stack:
                node = stack.pop()
                if node in visited:
                    continue
                visited.add(node)
                stack.extend(graph[node])
    return count

print("连通分量:", components(graph))

