grid = [
    ["1", "1", "0", "0"],
    ["1", "1", "0", "1"],
    ["0", "0", "1", "1"],
]

def num_islands(grid):
    count = 0

    def sink(r, c):
        if 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == "1":
            grid[r][c] = "0"
            sink(r + 1, c)
            sink(r - 1, c)
            sink(r, c + 1)
            sink(r, c - 1)

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == "1":
                count += 1
                sink(r, c)
    return count

print(num_islands(grid))

